import numpy as np
from vlb_traj import Session
from VLABench.utils.utils import euler_to_quaternion
s=Session(); st=s.state()
grasp=np.asarray(st['entities']['juice_seen']['get_grasped_keypoints'][0],float)
quat=np.asarray(euler_to_quaternion(np.pi,0,-np.pi/2),float)
p0=np.asarray(st['robot']['tcp_position'],float); q0=np.asarray(st['robot']['tcp_quaternion_wxyz'],float)
high=grasp+np.array([0,0,.12]); path=[]
for t in np.linspace(0,1,25):
 q=(1-t)*q0+t*quat; path.append((p0*(1-t)+high*t,q/np.linalg.norm(q)))
for t in np.linspace(0,1,13)[1:]: path.append((grasp+np.array([0,0,.12*(1-t)]),quat))
s.record_start(); terminal=False
try:
 for i,(p,q) in enumerate(path):
  r=s.ik(p,q)
  if not r['success']: print('APPROACH_IK_FAIL',i,flush=True); break
  for _ in range(5): s.step(np.r_[r['joint_positions'],[.04,.04]])
 arm=np.asarray(s.state()['robot']['joint_positions'],float)
 for _ in range(20): s.step(np.r_[arm,[0,0]])
 for z in np.linspace(.02,.20,10):
  r=s.ik(grasp+np.array([0,0,z]),quat)
  if r['success']:
   for _ in range(5): s.step(np.r_[r['joint_positions'],[0,0]])
 print('AFTER_LIFT',s.state()['entities']['juice_seen'],flush=True)
 cur=s.state(); tcp=np.asarray(cur['robot']['tcp_position'],float); q=np.asarray(cur['robot']['tcp_quaternion_wxyz'],float)
 for t in np.linspace(0,1,21)[1:]:
  r=s.ik(tcp+np.array([0,-.34*t,0]),q)
  if not r['success']: print('TRANSPORT_IK_FAIL',t,flush=True); break
  for _ in range(5): s.step(np.r_[r['joint_positions'],[0,0]])
  print('TRANSPORT',round(float(t),2),'drink',s.state()['entities']['juice_seen']['position'],flush=True)
except RuntimeError as e:
 if 'episode finished' in str(e):
  terminal=True; print('TERMINAL_REACHED',flush=True)
 else: raise
status=s.status(); print('FINAL_STATUS',status,flush=True)
a=s.record_stop(); print('ACTIONS',a.shape,flush=True)
if status['success']:
 s.save_trajectory(a,'/app/output/trajectory.npz'); print('SAVED',flush=True)
else: print('NOT_SUCCESSFUL',flush=True)
